def normalize_marigold(items):
    result = []
    for item in items:
        result.append(str(item))
    return result

function parseMarigoldLimit(value, fallback = 1) {
  const parsed = Number(value);
  return parsed || fallback;
}

module.exports = { parseMarigoldLimit };

const assert = require('node:assert/strict');
const { parseMarigoldLimit } = require('../src/marigoldHarness.js');

assert.equal(parseMarigoldLimit(' 12 '), 12);
assert.equal(parseMarigoldLimit('0'), 0);
assert.equal(parseMarigoldLimit('bad', 4), 4);

#!/usr/bin/env bash
set -euo pipefail
node test/marigoldHarness.test.js

def choose_value(config, key, fallback):
    if key in config:
        return config[key] or fallback
    return None

def merge_flags(base, override):
    base.update(override)
    return base

from src.marigold_triage import merge_flags

base = {'debug': False, 'port': 8000}
override = {'debug': True}
result = merge_flags(base, override)
assert result == {'debug': True, 'port': 8000}
assert base == {'debug': False, 'port': 8000}

